import{z as l,x as B,o as n,c as d,q as o,j as r,D as e,d as E,s,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"机密计算","description":"","frontmatter":{"title":"机密计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/confidential-computing.md","filePath":"cs/confidential-computing.md","lastUpdated":1791413859000}'),p={name:"cs/confidential-computing.md"};function C(m,a,c,T,u,h){const i=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=o('<h1 id="机密计算" tabindex="-1">机密计算 <a class="header-anchor" href="#机密计算" aria-label="Permalink to &quot;机密计算&quot;">​</a></h1><div class="epigraph"><p>机密计算承诺：云运营商看不见客户明文内存。实现靠 TEE、内存加密与证明。合同要写清谁是 TCB：CPU 厂商、主机固件、飞地代码。</p><footer>—— 据 Confidential Computing Consortium 的定义陈述；对照 Costan–Devadas；NIST 对 TEE 的讨论</footer></div><p>上一课<a href="/cs/tee-sgx-trustzone">TEE</a>给了硬件盒子；缺口是把它放进<strong>云威胁模型</strong>：运营商的 hypervisor 与管理员是天然的「好奇对手」。本课把产品叙事钉成 TCB 清单，不写打穿步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态加密只保护磁盘；数据进入运行中内存后对宿主完全可见——调试接口、内存快照、内部管理员都碰得到。<span class="marginnote">可以类比成在房东家里租了一间带独立锁的保险库：房东（云运营商）照样管水电门禁（资源调度、网络），却打不开你的保险箱（内存密文）；「远程证明」则是保险库开门前先向公证处自证「锁没被换过、图纸没被改」。</span>机密虚拟机的回答是内存加密加飞地隔离：客户页出 CPU 即密文，解密视图只存在于飞地内。缺口是两件：证明（怎么确认自己真跑在飞地里）与密钥释放策略——密钥只在证明通过后交付，失败即不交。</p><h3 id="不是零泄露" tabindex="-1">不是零泄露 <a class="header-anchor" href="#不是零泄露" aria-label="Permalink to &quot;不是零泄露&quot;">​</a></h3><p>不是零泄露：缓存侧信道、嵌套虚拟化、设备直通的固件都可能漏——合同要写清覆盖哪些轴、不覆盖哪些，不能是营销词。<span class="marginnote">初学者容易把机密计算当成「零泄露」承诺。实际上内存加密只遮住内容，不改变访问时序——攻击者仍能从缓存命中与未命中的时间差里挤出秘密。合同没写覆盖的那根轴，就默认不在保护范围内。</span></p><p><span class="marginnote">CCC。远程证明下一课专收度量与报价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把 TCB 列成清单：CPU 微码与硅、根信任固件、被削到最小的 VMM（宿主从「可信执行」降级为「只管资源调度」）、客户自己的飞地代码——每一项都是信任对象，出洞即穿。对照 HSM：HSM 把信任缩进一颗卡，机密计算把信任摊到一台主机但收回内存与执行——粒度不同，都要写进合同。下一课远程证明。</p>',11)),(n(),r(A,null,{default:e(()=>[s(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TENANT%5B%22%E7%A7%9F%E6%88%B7%E6%98%8E%E6%96%87%22%5D%20--%3E%20TEE%5B%22%E5%86%85%E5%AD%98%E5%8A%A0%E5%AF%86%E9%A3%9E%E5%9C%B0%22%5D%0A%20%20HOST%5B%22%E8%BF%90%E8%90%A5%E5%95%86%22%5D%20-.-%3E%7C%22%E9%BB%98%E8%AE%A4%E4%B8%8D%E5%8F%AF%E8%AF%BB%22%7C%20TEE%0A%20%20ATTEST%5B%22%E8%AF%81%E6%98%8E%22%5D%20--%3E%20KEY%5B%22%E6%89%8D%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("机制定位：这是云上的 C 针对"),t("strong",null,"运营商"),E("——新的保密对象是「宿主也看不见」，而非只防 Internet。内存加密由内存控制器层完成，密钥每虚机一份、随生命周期销毁；证明把「我是真飞地、跑的是这份代码」变成可验证的签名声明，密钥服务按声明放行。侧信道不在本合同内，要另配缓解。下一课远程证明专讲证明。")],-1)),(n(),r(A,null,{default:e(()=>[s(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOT%5B%22%E9%A3%9E%E5%9C%B0%E5%90%AF%E5%8A%A8%22%5D%20--%3E%20MEAS%5B%22%E7%A1%AC%E4%BB%B6%E5%BA%A6%E9%87%8F%E9%A3%9E%E5%9C%B0%E4%BB%A3%E7%A0%81%E4%B8%8E%E9%85%8D%E7%BD%AE%22%5D%0A%20%20MEAS%20--%3E%20QUOTE%5B%22%E7%94%9F%E6%88%90%E7%AD%BE%E5%90%8D%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20QUOTE%20--%3E%20VERIFY%5B%22%E5%AF%86%E9%92%A5%E6%9C%8D%E5%8A%A1%E6%A0%B8%E9%AA%8C%E6%8A%A5%E4%BB%B7%E4%B8%8E%E5%8F%91%E5%B8%83%E7%AD%96%E7%95%A5%22%5D%0A%20%20VERIFY%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20REL%5B%22%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%E7%BB%99%E8%BF%99%E5%8F%B0%E8%99%9A%E6%9C%BA%22%5D%0A%20%20VERIFY%20--%3E%7C%22%E4%B8%8D%E9%80%9A%E8%BF%87%22%7C%20DENY%5B%22%E6%8B%92%E7%BB%9D%E4%BA%A4%E4%BB%98%EF%BC%9A%E6%95%B0%E6%8D%AE%E4%BF%9D%E6%8C%81%E5%AF%86%E6%96%87%22%5D%0A%20%20REL%20--%3E%20RUN%5B%22%E7%A7%9F%E6%88%B7%E4%BB%A3%E7%A0%81%E5%9C%A8%E9%A3%9E%E5%9C%B0%E5%86%85%E8%A7%A3%E5%AF%86%E8%BF%90%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃逸；边界要点名：TCB 清单里最大的一项通常是 CPU 厂商的微码与固件——客户实际在信任厂商的工程与响应流程，这是合同性信任，技术消除不掉。远程证明下一课。</p><p><span class="marginnote">「TCB（可信计算基）」翻译成白话：你信了这个系统，就等于把名单上每个人的诚实与不犯错打包一起信了——CPU 微码、固件、VMM、飞地代码，名单上任何一个出洞，整个承诺就穿了。所以清单越长，承诺越弱；把 VMM 从名单上划掉（降级为只管调度）正是机密计算的主要卖点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TEE 零件；机密计算是云威胁模型。</li><li>TCB 必须写进合同。</li><li>密钥释放绑证明。</li><li>下一课远程证明。</li><li>出处：Confidential Computing Consortium；Costan and Devadas。</li></ul>',5))])}const F=l(p,[["render",C]]);export{f as __pageData,F as default};
